          color: const Color(0xFF241D40),
          borderRadius: const BorderRadius.only(
            topLeft: Radius.circular(15),
            topRight: Radius.circular(15),
            bottomLeft: Radius.circular(15),
          ),
          border: Border.all(color: const Color(0xFF49396F)),
