class BottomNavigation extends StatelessWidget {
  final int selectedIndex;
  final ValueChanged<int> onSelected;

  const BottomNavigation({
    super.key,
    required this.selectedIndex,
    required this.onSelected,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 68,
      decoration: const BoxDecoration(
        color: kBottom,
        border: Border(
          top: BorderSide(
            color: kLine,
            width: 1,
          ),
        ),
      ),
      child: Row(
        children: [
          bottomItem(0, Icons.sentiment_satisfied_alt_outlined, 'Navi'),
          bottomItem(1, Icons.chat_bubble_outline, 'Conversa'),
          bottomItem(2, Icons.article_outlined, 'Diário'),
          bottomItem(3, Icons.account_balance_outlined, 'Cidade'),
          bottomItem(4, Icons.people_outline, 'Encontros'),
        ],
      ),
    );
  }

  Widget bottomItem(int index, IconData icon, String label) {
    final selected = selectedIndex == index;

    return Expanded(
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () => onSelected(index),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Container(
              width: 27,
              height: 23,
              decoration: selected
                  ? BoxDecoration(
                      color: const Color(0xFF251B4B),
                      borderRadius: BorderRadius.circular(12),
                    )
                  : null,
              child: Icon(
                icon,
                size: 17,
                color: selected ? kPurple : const Color(0xFF8C8798),
              ),
            ),
            const SizedBox(height: 4),
            Text(
              label,
              style: TextStyle(
                color: selected ? kPurple : const Color(0xFF898494),
                fontSize: 9,
                fontWeight:
                    selected ? FontWeight.bold : FontWeight.normal,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ============================================================
// CÍRCULOS DO CHÃO
// ============================================================

class GroundCirclesPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = const Color(0xFF6CEFF1)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.8;

    final center = Offset(size.width / 2, size.height / 2);

    canvas.drawOval(
      Rect.fromCenter(
        center: center,
        width: size.width - 8,
        height: 23,
      ),
      paint,
    );

    canvas.drawOval(
      Rect.fromCenter(
        center: Offset(center.dx, center.dy + 1),
        width: size.width * 0.74,
        height: 17,
      ),
      paint,
    );

    canvas.drawOval(
      Rect.fromCenter(
        center: Offset(center.dx, center.dy + 1),
        width: size.width * 0.47,
        height: 11,
      ),
      paint,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}
